// The Go backend, as generated by `wails3 generate bindings`.
export * as Deck from "../../bindings/github.com/mepkn/agentdeck/desktop/deckservice";
export type { Info, Snapshot } from "../../bindings/github.com/mepkn/agentdeck/desktop/internal/sessions/models";
export type { Item, Tool, Info as AgentInfo } from "../../bindings/github.com/mepkn/agentdeck/desktop/internal/agents/models";
export type { Prompt } from "../../bindings/github.com/mepkn/agentdeck/desktop/internal/screen/models";
export type { Project } from "../../bindings/github.com/mepkn/agentdeck/desktop/internal/store/models";

export function errorMessage(e: unknown, fallback = "Something went wrong."): string {
  if (e instanceof Error && e.message) return e.message;
  if (typeof e === "string" && e) return e;
  return fallback;
}
